.card-highlight {
  border: 2px solid var(--sl-primary);
  box-shadow: 0 0 15px rgba(var(--sl-primary-rgb), 0.2);
  position: relative;
}

.card-highlight .btn-primary {
  background-color: var(--sl-primary);
  border-color: var(--sl-primary);
}

.card-highlight .btn-primary:hover {
  background-color: var(--sl-primary);
  border-color: var(--sl-primary);
  opacity: 0.9;
}

.form-check-input:checked {
  background-color: var(--sl-primary);
  border-color: var(--sl-primary);
}

.form-check-input:focus {
  box-shadow: 0 0 0 0.25rem rgba(var(--sl-primary-rgb), 0.25);
}

variante_1.js:
document.addEventListener('DOMContentLoaded', function() {
  const pricingToggle = document.getElementById('pricingToggle');
  const priceMonthlyElements = document.querySelectorAll('.price-monthly');
  const priceAnnualElements = document.querySelectorAll('.price-annual');
  const pricePeriodElements = document.querySelectorAll('.card-text .text-muted');

  if (pricingToggle) {
    pricingToggle.addEventListener('change', function() {
      if (this.checked) { // Anual
        priceMonthlyElements.forEach(el => el.classList.add('d-none'));
        priceAnnualElements.forEach(el => el.classList.remove('d-none'));
        pricePeriodElements.forEach(el => el.textContent = '/ano');
      } else { // Mensal
        priceMonthlyElements.forEach(el => el.classList.remove('d-none'));
        priceAnnualElements.forEach(el => el.classList.add('d-none'));
        pricePeriodElements.forEach(el => el.textContent = '/mês');
      }
    });
  }
});

